import sys

def count_numbers_with_power_of_2(n, e):
    power_of_2 = str(2 ** e)
    length = len(power_of_2)

    # dp[i][j] will store the number of ways to form a number of length i
    # ending with digit j that contains the power of 2 as a substring
    dp = [[0] * 10 for _ in range(length + 1)]
    dp[0][0] = 1

    for i in range(length):
        for d in range(10):
            for j in range(length):
                if power_of_2[j] == str(d):
                    dp[j + 1][d] += dp[i][d]
                else:
                    dp[i + 1][d] += dp[i][d]

    count = 0
    for i in range(1, length + 1):
        for d in range(10):
            count += dp[i][d]

    # Check numbers directly up to n
    for k in range(n + 1):
        if power_of_2 in str(k):
            count += 1

    return count

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    e = int(data[1])
    result = count_numbers_with_power_of_2(n, e)
    print(result)

if __name__ == "__main__":
    main()
